import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String a = sc.next();
        String b = sc.next();
        try {
            int result = divide(a, b);
            System.out.println("Result: " + result);
        } catch (RuntimeException e) {
            System.out.println("Handled in main: " + e.getMessage());
        }
    }

    static int parse(String token) throws NumberFormatException {
        return Integer.parseInt(token);
    }

    static int divide(String a, String b) throws NumberFormatException, ArithmeticException {
        int x = parse(a);
        int y = parse(b);
        return x / y;
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String type = sc.next();
        String value = sc.next();
        try {
            process(type, value);
        } catch (NumberFormatException e) {
            System.out.println("Number problem: bad number");
        } catch (IllegalArgumentException e) {
            System.out.println("Argument problem: " + e.getMessage());
        } catch (Exception e) {
            System.out.println("General problem: " + e.getMessage());
        }
    }

    static void process(String type, String value) throws Exception {
        if (type.equals("num")) {
            int v = Integer.parseInt(value);
            System.out.println("Parsed: " + v);
        } else if (type.equals("arg")) {
            if (value.length() < 3) {
                throw new IllegalArgumentException("Short argument: " + value);
            }
            System.out.println("Arg ok: " + value);
        } else {
            throw new Exception("Unknown type: " + type);
        }
    }
}

