import java.util.Scanner;

public class Main {
    static long balance;
    static int failures;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        balance = sc.nextLong();
        for (int i = 0; i < n; i++) {
            String op = sc.next();
            try {
                if (op.equals("DEPOSIT")) {
                    deposit(sc.nextLong());
                } else if (op.equals("WITHDRAW")) {
                    withdraw(sc.nextLong());
                } else {
                    System.out.println("Balance: " + balance);
                }
            } catch (NegativeAmountException e) {
                failures++;
                System.out.println("Rejected: " + e.getMessage());
            } catch (InsufficientFundsException e) {
                failures++;
                System.out.println("Rejected: " + e.getMessage());
            }
        }
        System.out.println("Final balance: " + balance);
        System.out.println("Failed operations: " + failures);
    }

    static void deposit(long amount) throws NegativeAmountException {
        if (amount < 0) {
            throw new NegativeAmountException("Negative amount: " + amount);
        }
        balance += amount;
        System.out.println("Deposited: " + amount);
    }

    static void withdraw(long amount) throws NegativeAmountException, InsufficientFundsException {
        if (amount < 0) {
            throw new NegativeAmountException("Negative amount: " + amount);
        }
        if (amount > balance) {
            throw new InsufficientFundsException("Insufficient funds: " + amount);
        }
        balance -= amount;
        System.out.println("Withdrawn: " + amount);
    }
}

class InsufficientFundsException extends Exception {
    InsufficientFundsException(String message) {
        super(message);
    }
}

class NegativeAmountException extends Exception {
    NegativeAmountException(String message) {
        super(message);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int succeeded = 0;
        int failed = 0;
        for (int i = 0; i < n; i++) {
            String name = sc.next();
            int code = sc.nextInt();
            try {
                System.out.println("Open " + name);
                if (code < 0) {
                    throw new IllegalArgumentException("Bad code: " + code);
                }
                System.out.println("Run " + name);
                succeeded++;
            } catch (IllegalArgumentException e) {
                failed++;
                System.out.println("Error in " + name + ": " + e.getMessage());
            } finally {
                System.out.println("Close " + name);
            }
        }
        System.out.println("Successful jobs: " + succeeded);
        System.out.println("Failed jobs: " + failed);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        try {
            int result = compute(a, b);
            System.out.println("Result: " + result);
        } catch (IllegalStateException e) {
            System.out.println("Error: " + e.getMessage());
            System.out.println("Caused by: " + e.getCause().getMessage());
        }
    }

    static int compute(int a, int b) {
        try {
            return a / b;
        } catch (ArithmeticException e) {
            throw new IllegalStateException("Computation failed for inputs " + a + " and " + b, e);
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long sum = 0;
        int valid = 0;
        int invalid = 0;
        for (int i = 0; i < n; i++) {
            String token = sc.next();
            try {
                int value = Integer.parseInt(token);
                sum += value;
                valid++;
            } catch (NumberFormatException e) {
                invalid++;
            }
        }
        System.out.println("Valid entries: " + valid);
        System.out.println("Invalid entries: " + invalid);
        System.out.println("Total sum: " + sum);
    }
}
